#include <string>
#include <vector>

std::vector<std::string> splitCommandLine(const std::string& line)
{
    std::vector<std::string> args;
    std::string current;
    bool inArg{ false }, quoted{ false };
    std::size_t i{ 0 };
    while (i < line.size())
    {
        const char c{ line[i] };
        if ((c == ' ' || c == '\t') && !quoted)
        {
            if (inArg) { args.push_back(current); current.clear(); inArg = false; }
            ++i;
            continue;
        }
        inArg = true;
        if (c == '\\')
        {
            std::size_t n{ 0 };
            while (i < line.size() && line[i] == '\\') { ++n; ++i; }
            if (i < line.size() && line[i] == '"')
            {
                current.append(n / 2, '\\');
                if (n % 2 == 1) { current += '"'; ++i; }      // escaped quote
                // even: the quote is handled as a toggle on the next pass
            }
            else current.append(n, '\\');
            continue;
        }
        if (c == '"') { quoted = !quoted; ++i; continue; }
        current += c;
        ++i;
    }
    if (inArg) args.push_back(current);
    return args;
}

std::string quoteArgument(const std::string& arg)
{
    if (!arg.empty() && arg.find_first_of(" \t\"") == std::string::npos) return arg;
    std::string out{ "\"" };
    std::size_t backslashes{ 0 };
    for (char c : arg)
    {
        if (c == '\\') { ++backslashes; continue; }
        if (c == '"') { out.append(backslashes * 2 + 1, '\\'); out += '"'; }
        else { out.append(backslashes, '\\'); out += c; }
        backslashes = 0;
    }
    out.append(backslashes * 2, '\\');
    out += '"';
    return out;
}

std::string buildCommandLine(const std::vector<std::string>& args)
{
    std::string line;
    for (std::size_t i{ 0 }; i < args.size(); ++i) line += (i ? " " : "") + quoteArgument(args[i]);
    return line;
}

