using Args = std::vector<std::string>;
TEST("splitting") {
    CHECK_EQ(splitCommandLine("tool.exe  --in-place   notes.md"), (Args{ "tool.exe", "--in-place", "notes.md" }));
    CHECK_EQ(splitCommandLine("\"C:\\My Notes\\a.md\" x"), (Args{ "C:\\My Notes\\a.md", "x" }));
    CHECK_EQ(splitCommandLine("a\" b\"c \"\" d"), (Args{ "a bc", "", "d" }));
    CHECK_EQ(splitCommandLine("C:\\dir\\ \"C:\\My Folder\\\\\" end"), (Args{ "C:\\dir\\", "C:\\My Folder\\", "end" }));
    CHECK_EQ(splitCommandLine("say \\\"hi\\\" a\\\\\\\"b"), (Args{ "say", "\"hi\"", "a\\\"b" }));
    CHECK(splitCommandLine("   ").empty());
}
TEST("quoting") {
    CHECK_EQ(quoteArgument("plain"), std::string("plain")); CHECK_EQ(quoteArgument(""), std::string("\"\""));
    CHECK_EQ(quoteArgument("C:\\My Folder\\"), std::string("\"C:\\My Folder\\\\\"")); CHECK_EQ(quoteArgument("C:\\dir\\"), std::string("C:\\dir\\"));
    CHECK_EQ(quoteArgument("say \"hi\""), std::string("\"say \\\"hi\\\"\"")); CHECK_EQ(quoteArgument("a\\\"b"), std::string("\"a\\\\\\\"b\""));
}
TEST("round trips") {
    const std::vector<Args> cases{
        { "tool.exe", "C:\\My Folder\\", "x" }, { "a", "", "b" }, { "quote\"inside", "tab\there", "back\\\\slashes\\" },
        { "\\\"", "\\\\\"\\", " ", "--name=\"Sam Smith\"" }, { "trailing\\\\" },
    };
    for (const Args& a : cases) CHECK_EQ(splitCommandLine(buildCommandLine(a)), a);
}

